from .file_transfer_factory import FileGetterFactory, FilePutterFactory
from taf.internal.core import camel_case


def _CreatingFileTransfer(
        attr_name,
        file_transfer_config_name,
        mixin_class_name,
        factory_class):

    class CreatingFileTransferTemplate(object):
        def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
            super(CreatingFileTransferTemplate, self)._build_arguments(
                configuration=configuration,
                existing_arguments=existing_arguments,
                resulting_arguments=resulting_arguments)
            resulting_arguments[attr_name] = factory_class().create(
                configuration={'type': 'cat',
                               'executor': {'type': 'local'}} if file_transfer_config_name is None else configuration[
                                   file_transfer_config_name],
                existing_arguments=existing_arguments)

    return type(mixin_class_name, (CreatingFileTransferTemplate,), {})


def CreatingFileGetter(
        attr_name,
        file_transfer_config_name="file_transfer"):
    mixin_class_name = "Creating" + camel_case(attr_name) + "TypeFileGetter"
    factory_class = FileGetterFactory

    return _CreatingFileTransfer(attr_name, file_transfer_config_name, mixin_class_name, factory_class)


def CreatingFilePutter(
        attr_name,
        file_transfer_config_name="file_transfer"):
    mixin_class_name = "Creating" + camel_case(attr_name) + "TypeFilePutter"
    factory_class = FilePutterFactory

    return _CreatingFileTransfer(attr_name, file_transfer_config_name, mixin_class_name, factory_class)
